  Frozen = { key = "Frozen", name = "ICE COLD", desc = "An advanced style for racers eager to take advantage of Frozen.", short = "An advanced style for racers eager to take advantage of Frozen.", rich = "An advanced style for racers eager to take advantage of Frozen.", path = "/Game/Griffin/Gameplay/Campaign/Loadouts/RacerStyles/CAM_Style_Frozen_Lv3.CAM_Style_Frozen_Lv3", icon = "Icons/RacerStyles/T_UI_RacerStyle_Frozen_Icn", bg = "Content/RacerStyles/T_UI_RacerStyle_Frozen_Bg", traits = { "TRT_FrozenRamjetNoHeat", "TRT_OnFrozenGainShield", "TRT_FrozenDoubleDuration" }, pod = false },
  Pod_Cabbage = { key = "Pod_Cabbage", name = "VULPTEREEN 327", desc = "Built on his homeworld of Vulpter, the Vulptereen 327 podracer is perfect for the aggressive Dud Bolt, boasting excellent traction to power down straights. A vehicle built tough, Dud Bolt's favorite pastime is ramming into his opponents as he flies by unscathed, laughing as he does.", short = "Built on his homeworld of Vulpter, the Vulptereen 327 podracer is perfect for the aggressive Dud Bolt, boasting excellent traction to power down straights.", rich = "Built on his homeworld of Vulpter, the Vulptereen 327 podracer is perfect for the aggressive Dud Bolt, boasting excellent traction to power down straights. A vehicle built tough, Dud Bolt's favorite pastime is ramming into his opponents as he flies by unscathed, laughing as he does.", path = "/Game/Griffin/Gameplay/Campaign/Loadouts/RacerStyles/Pvp_IA_Plane_Cabbage.Pvp_IA_Plane_Cabbage", icon = "Content/Characters/T_UI_PlaneChar_Cabbage_Thumb", traits = { "TRT_AfterburnerRefillOnPerfectLanding", "TRT_AfterburnerPowerStacksWhenAirborne", "TRT_AllLandingsArePerfect" }, pod = true, base = "Airborne" },
  Pod_Celery = { key = "Pod_Celery", name = "CUSTOM ORD PEDROVIA", desc = "Built from scratch to suit Gasgano's needs, his custom Ord Pedrovia podracer features a bespoke Afterburner tank, easily leaving competitors in the dust. Though this strength comes at the cost of increased drag, it's no matter to Gasgano, who's already pulled into the lead.", short = "Built from scratch to suit Gasgano's needs, his custom Ord Pedrovia podracer features a bespoke Afterburner tank, easily leaving competitors in the dust.", rich = "Built from scratch to suit Gasgano's needs, his custom Ord Pedrovia podracer features a bespoke Afterburner tank, easily leaving competitors in the dust. Though this strength comes at the cost of increased drag, it's no matter to Gasgano, who's already pulled into the lead.", path = "/Game/Griffin/Gameplay/Campaign/Loadouts/RacerStyles/Pvp_IA_Plane_Celery.Pvp_IA_Plane_Celery", icon = "Content/Characters/T_UI_PlaneChar_Celery_Thumb", traits = { "TRT_BetterTopSpeedWhenNoCrashes", "TRT_GainSurgeOnShieldLoss", "TRT_OneMoreCrash" }, pod = true, base = "Defence" },
  Pod_Garlic = { key = "Pod_Garlic", name = "IPG-X1131 LONGTAIL", desc = "Teemto Pagalies' IPG-X1131 LongTail features a unique circular shape. The internal cycling ring functions as a gyroscopic stabilizer, allowing it to keep up with more aerodynamic podracers. But what improvements the cycling ring grants in cornering, it sacrifices in speed.", short = "Teemto Pagalies' IPG-X1131 LongTail features a unique circular shape.", rich = "Teemto Pagalies' IPG-X1131 LongTail features a unique circular shape. The internal cycling ring functions as a gyroscopic stabilizer, allowing it to keep up with more aerodynamic podracers. But what improvements the cycling ring grants in cornering, it sacrifices in speed.", path = "/Game/Griffin/Gameplay/Campaign/Loadouts/RacerStyles/Pvp_IA_Plane_Garlic.Pvp_IA_Plane_Garlic", icon = "Content/Characters/T_UI_PlaneChar_Garlic_Thumb", traits = { "TRT_SurgeWhenSysMalfRecovery", "TRT_RecoverFromSysMalfFaster", "TRT_MalfunctionRepairOnRecovery" }, pod = true, base = "Malfunction" },
  Pod_Swede = { key = "Pod_Swede", name = "PLUG-F MAMMOTH", desc = "The legendary Sebulba's Plug-F Mammoth is an icon as well as a brute, boasting a robust exterior designed to take down opponents while preserving its own integrity. That isn't to mention the removable systems built for bending former track regulations, such as flame vents.", short = "The legendary Sebulba's Plug-F Mammoth is an icon as well as a brute, boasting a robust exterior designed to take down opponents while preserving its own integrity.", rich = "The legendary Sebulba's Plug-F Mammoth is an icon as well as a brute, boasting a robust exterior designed to take down opponents while preserving its own integrity. That isn't to mention the removable systems built for bending former track regulations, such as flame vents.", path = "/Game/Griffin/Gameplay/Campaign/Loadouts/RacerStyles/Pvp_IA_Plane_Swede.Pvp_IA_Plane_Swede", icon = "Content/Characters/T_UI_PlaneChar_Nesodon_Thumb", traits = { "TRT_EnergyForTakedowns", "TRT_SurgeForTakedowns", "TRT_SurgeForTakedownsUpgrade" }, pod = true, base = "BattlingFlameVent" },
  Pod_Onion = { key = "Pod_Onion", name = "BT310 QUADRA", desc = "Named for its four engines, the BT310 Quadra was originally a factory-built rental. Ben Quadinaros refitted the vehicle with new power couplings and custom systems, taming the powerful, but temperamental podracer.", short = "Named for its four engines, the BT310 Quadra was originally a factory-built rental.", rich = "Named for its four engines, the BT310 Quadra was originally a factory-built rental. Ben Quadinaros refitted the vehicle with new power couplings and custom systems, taming the powerful, but temperamental podracer.", path = "/Game/Griffin/Gameplay/Campaign/Loadouts/RacerStyles/Pvp_IA_Plane_Onion.Pvp_IA_Plane_Onion", icon = "Content/Characters/T_UI_PlaneChar_Onion_Thumb", traits = { "TRT_StrongerAfterburner", "TRT_AfterburnerLastsLonger", "TRT_RefillAfterburnerOnOvertake" }, pod = true, base = "Afterburner" },
  Pod_Pepper = { key = "Pod_Pepper", name = "EXELBROK XL 5115", desc = "Speed is no challenge for the Exelbrok XL 5115, thanks to cycles of work done by Ody's loyal pit droid team on the podracer's immense twin engines. Even with its reduced cornering, the vehicle is a marvel waiting to be challenged.", short = "Speed is no challenge for the Exelbrok XL 5115, thanks to cycles of work done by Ody's loyal pit droid team on the podracer's immense twin engines.", rich = "Speed is no challenge for the Exelbrok XL 5115, thanks to cycles of work done by Ody's loyal pit droid team on the podracer's immense twin engines. Even with its reduced cornering, the vehicle is a marvel waiting to be challenged.", path = "/Game/Griffin/Gameplay/Campaign/Loadouts/RacerStyles/Pvp_IA_Plane_Pepper.Pvp_IA_Plane_Pepper", icon = "Content/Characters/T_UI_PlaneChar_Pepper_Thumb", traits = { "TRT_BetterDrafting", "TRT_LongerDrafting", "TRT_BiggerDraftingZones" }, pod = true, base = "Drafting" },
}
